43	export class TransactionStreamCapacityError extends Error {}
44	
45	type Owner = ReturnType<typeof openTransactionStore>;
46	type ReceiptObservation = {
47	  readonly kind: "receipt";
48	  readonly receipt: TransactionReceipt;
49	  readonly context: TransactionReadContext;
50	};
51	export type TransactionServiceSubmissionResult =
52	  | Exclude<TransactionSubmissionResult, { readonly kind: "receipt" }>
53	  | ReceiptObservation;
54	export type TransactionServiceReceiptResult =
55	  | ReceiptObservation
56	  | { readonly kind: "refused"; readonly status: 401; readonly code: "unauthenticated" }
57	  | {
58	      readonly kind: "refused";
59	      readonly status: 404;
60	      readonly code: "resource-not-found";
61	      readonly context: TransactionReadContext;
62	    };
63	export interface TransactionServiceOptions {
64	  readonly ownerLifetime: "service";
65	  readonly read: TransactionReadOptions;
66	  /** Private scheduler must eventually deliver every uncancelled turn. No
67	   * delivery timeout is invented here; nondelivery also prevents drain. */
68	  readonly scheduler?: Pick<LifecycleScheduler, "turn">;
69	  /** Existing finite comparison policy; never a fresh deadline on each retry. */
70	  readonly comparison?: Parameters<typeof submitTransaction>[2];
71	  readonly minimumReads?: TransactionMinimumWaitOptions;
72	  readonly maximumStreams?: number;
73	}
