75	export function createTransactionService(owner: Owner, options: TransactionServiceOptions) {
76	  if (options.ownerLifetime !== "service")
77	    throw new TypeError("explicit service owner lifetime required");
78	  const scope = owner.scope;
79	  const supplied = options.read,
80	    limits = supplied.advertisedLimits,
81	    page = limits.page,
82	    selector = limits.selector,
83	    enforcedSelector = supplied.selectorLimits;
84	  const suppliedPagination = supplied.pagination;
85	  const pagination = { ...suppliedPagination };
86	  // Capture callback values once, but keep the receiver the Read plane used
87	  // before scalar snapshotting. Stateful callbacks belong to their caller,
88	  // not to the frozen copy. Leave invalid values for existing validation.
89	  const clock = pagination.clock,
90	    generateOpaqueToken = pagination.generateOpaqueToken;
91	  if (typeof clock === "function") pagination.clock = clock.bind(suppliedPagination);
92	  if (typeof generateOpaqueToken === "function")
93	    pagination.generateOpaqueToken = generateOpaqueToken.bind(suppliedPagination);
94	  const capturedRead: TransactionReadOptions = Object.freeze({
95	    selectorLimits: Object.freeze({
96	      bytes: enforcedSelector.bytes,
97	      depth: enforcedSelector.depth,
98	      nodes: enforcedSelector.nodes,
99	    }),
100	    pagination: Object.freeze(pagination),
101	    advertisedLimits: Object.freeze({
102	      page: Object.freeze({ defaultItems: page.defaultItems, maximumItems: page.maximumItems }),
103	      selector: Object.freeze({
104	        bytes: selector.bytes,
105	        depth: selector.depth,
106	        nodes: selector.nodes,
107	      }),
108	      cursorTtlMilliseconds: limits.cursorTtlMilliseconds,
109	    }),
110	  });
111	  const maximum = owner.readConfiguration().receiptMaximumItems;
112	  if (
113	    capturedRead.advertisedLimits.page.maximumItems !== maximum ||
114	    capturedRead.pagination.maxPageItems !== maximum
115	  )
116	    throw new TypeError("receipt page maximum differs from installed owner");
117	  const scheduler = options.scheduler ?? createNodeLifecycleScheduler();
118	  const turn = scheduler.turn.bind(scheduler);
119	  const comparison = Object.freeze({ ...options.comparison });
120	  const minimumReads = Object.freeze({ ...options.minimumReads });
121	  const read = createTransactionReadPlane(owner, capturedRead);
122	  const active = new Set<Promise<unknown>>();
123	  const mutations = new Set<Promise<unknown>>();
124	  const maximumStreams = options.maximumStreams ?? 1;
125	  if (!Number.isSafeInteger(maximumStreams) || maximumStreams < 1)
126	    throw new TypeError("invalid private stream capacity");
127	  const streams = new Map<AbortController, Promise<void>>();
128	  let accepting = true;
129	  let cleanupFailure: AggregateError | undefined;
130	  let closing: Promise<void> | undefined;
131	  const completion = Promise.withResolvers<void>();
132	  void completion.promise.catch(() => {});
133	  function check() {
134	    if (cleanupFailure)
135	      throw new Error("transaction service cleanup failed; close and reopen", {
136	        cause: cleanupFailure,
137	      });
138	    if (!accepting) throw new Error("transaction service is closing or closed");
139	  }
140	  function run<T>(start: () => Promise<T>): Promise<T> {
141	    check();
142	    const task = Promise.withResolvers<T>();
143	    active.add(task.promise);
144	    // Observe rejected detached delivery without changing what its caller sees.
145	    void task.promise.then(
146	      () => active.delete(task.promise),
147	      () => active.delete(task.promise),
148	    );
149	    try {
150	      task.resolve(start());
151	    } catch (error) {
152	      task.reject(error);
153	    }
154	    return task.promise;
155	  }
156	  function mutate<T>(start: () => Promise<T>): Promise<T> {
157	    const task = run(start);
158	    mutations.add(task);
159	    void task.then(
160	      () => mutations.delete(task),
161	      () => mutations.delete(task),
162	    );
163	    return task;
164	  }
165	  function nextTurn(): Promise<void> {
166	    return new Promise((resolve, reject) => {
167	      let scheduling = true,
168	        inline = false,
169	        live = true;
170	      let cancel: (() => void) | undefined;
171	      try {
172	        cancel = turn(() => {
173	          if (!live) return;
174	          if (scheduling) {
175	            inline = true;
176	            return;
177	          }
178	          live = false;
179	          resolve();
180	        });
181	        scheduling = false;
182	        if (typeof cancel !== "function") throw new TypeError("scheduler must return cancellation");
183	        if (inline) throw new TypeError("scheduler invoked callback inline");
184	      } catch (error) {
185	        live = false;
186	        try {
187	          if (typeof cancel === "function") cancel();
188	        } catch (cleanup) {
189	          reject(
190	            new AggregateError([error, cleanup], "transaction scheduling and cancellation failed"),
191	          );
192	          return;
193	        }
194	        reject(error);
195	      }
196	    });
197	  }
198	  function checked(observed: {
199	    readonly receipt: TransactionReceipt;
200	    readonly context: TransactionReadContext;
201	  }): ReceiptObservation {
202	    const results = observed.receipt.results;
203	    // URL prefixes are construction-guaranteed by this store; retain these
204	    // checks as defense in depth alongside the independent result bounds.
205	    if (
206	      observed.receipt.status === "completed" &&
207	      observed.receipt.detail === "available" &&
208	      (!Array.isArray(results) ||
209	        results.length === 0 ||
210	        results.length > capturedRead.advertisedLimits.page.maximumItems ||
211	        (observed.receipt.next !== null &&
212	          (typeof observed.receipt.next !== "string" ||
213	            !observed.receipt.next.startsWith(`${observed.receipt.id}/pages/`) ||
214	            results.length !== maximum)))
215	    )
216	      throw new Error("transaction receipt exceeds supported inline result bound", {
217	        cause: { id: observed.receipt.id, key: observed.receipt.idempotencyKey },
218	      });
219	    return Object.freeze({ kind: "receipt", ...observed });
220	  }
221	  function receipt(
222	    principal: string,
223	    id: string,
224	    minimum?: TransactionMinimum,
225	  ): ReceiptObservation | Extract<TransactionServiceReceiptResult, { readonly status: 404 }> {
226	    const observed = owner.readReceipt(principal, id, minimum);
227	    return observed.receipt === undefined
228	      ? Object.freeze({
229	          kind: "refused",
230	          status: 404,
231	          code: "resource-not-found",
232	          context: observed.context,
233	        })
234	      : checked({ ...observed, receipt: observed.receipt });
235	  }
236	  async function executeSequence(
237	    principal: string,
238	    sequence: PreparedTransactionSequence,
239	  ): Promise<TransactionSequenceResponse> {
240	    const stepper = createTransactionSequenceStepper(owner, principal, sequence);
241	    try {
242	      for (;;) {
243	        await nextTurn();
244	        const step = stepper.step();
245	        if (step.done) {
246	          if (!step.response) throw new Error("completed sequence lost response");
247	          return step.response;
248	        }
249	      }
250	    } catch (error) {
251	      try {
252	        stepper.abort();
253	      } catch (cleanup) {
254	        cleanupFailure = new AggregateError(
255	          [...(cleanupFailure ? [cleanupFailure] : []), error, cleanup],
256	          "transaction sequence and cleanup failed",
257	        );
258	        throw cleanupFailure;
259	      }
260	      throw error;
261	    }
262	  }
263	  return Object.freeze({
264	    scope,
265	    /** Internal candidate only: no wire exposure or readiness assertion. Without
266	     * a minimum the synchronous observation does not inspect signal. */
267	    discoveryObserved(supplied?: TransactionMinimum, signal?: AbortSignal) {
268	      const minimum = supplied === undefined ? undefined : snapshotCurrentReadMinimum(supplied);
269	      const observe = () => {
270	        const observed = owner.withRead((_reader, context) => {
271	          if (minimum !== undefined) checkCurrentReadMinimum(minimum, context, true);
272	          return Object.freeze({
273	            scopeEpoch: context.scopeEpoch,
274	            authorizationView: context.authorizationView,
275	            scopePosition: context.scopePosition,
276	          });
277	        });
278	        if (observed.kind === "entry-refused")
279	          throw new Error("transaction discovery observation refused", { cause: observed.cause });
280	        return observed.value;
281	      };
282	      const assemble = (context: TransactionReadContext) =>
283	        Object.freeze({
284	          ...assembleTransactionDiscovery(scope, context, capturedRead.advertisedLimits),
285	          context,
286	        });
287	      // Preserve zero-minimum entry timing. A minimum-bearing call owns one
288	      // finite lifetime; neither waits nor parsing retain a live owner entry.
289	      if (minimum === undefined) return run(async () => assemble(observe()));
290	      return run(async () =>
291	        assemble(await waitForTransactionMinimum(observe, minimumReads, signal)),
292	      );
293	    },
294	    /** Separate cancellable lifetime, never an infinite finite-work drain. The
295	     * callback starts only after capacity registration and abort wiring. */
296	    stream(
297	      start: (signal: AbortSignal) => Promise<void>,
298	      supplied: AbortSignal,
299	      expected?: TransactionReadContext,
300	    ): Promise<void> {
301	      check();
302	      if (supplied.aborted) return Promise.reject(supplied.reason);
303	      if (streams.size >= maximumStreams)
304	        throw new TransactionStreamCapacityError("private live stream capacity reached");
305	      const selected = expected ?? owner.withRead((_reader, context) => context);
306	      const context =
307	        "kind" in selected ? (selected.kind === "read" ? selected.value : undefined) : selected;
308	      if (!context) throw new Error("stream context observation refused");
309	      const lease = owner.acquireAuthorizationLease(context);
310	      const controller = new AbortController();
311	      const revoke = () => controller.abort(lease.signal.reason);
312	      lease.signal.addEventListener("abort", revoke, { once: true });
313	      const abort = () => controller.abort(supplied.reason);
314	      supplied.addEventListener("abort", abort, { once: true });
315	      const task = Promise.withResolvers<void>();
316	      streams.set(controller, task.promise);
317	      const finish = () => {
318	        supplied.removeEventListener("abort", abort);
319	        streams.delete(controller);
320	        lease.signal.removeEventListener("abort", revoke);
321	        lease.release();
322	      };
323	      void task.promise.then(finish, finish);
324	      try {
325	        task.resolve(start(controller.signal));
326	      } catch (error) {
327	        task.reject(error);
328	      }
329	      return task.promise;
330	    },
331	    /** Trusted administration, never HTTP. Cancellation stops waiting, not writes. */
332	    replaceAuthorizationPolicy(options: {
333	      readonly timeoutMs: number;
334	      readonly signal?: AbortSignal;
335	    }) {
336	      const timeoutMs = options.timeoutMs,
337	        signal = options.signal;
338	      if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 2147483647)
339	        throw new TypeError("finite administrative timeout required");
340	      check();
341	      signal?.throwIfAborted();
342	      const deadline = performance.now() + timeoutMs;
343	      const resume = owner.pauseMutationAdmission();
344	      return run(async () => {
345	        let abort: (() => void) | undefined;
346	        let timer: ReturnType<typeof setTimeout> | undefined;
347	        try {
348	          const cancelled = new Promise<never>((_resolve, reject) => {
349	            abort = () => reject(signal?.reason);
350	            signal?.addEventListener("abort", abort, { once: true });
351	            timer = setTimeout(() => reject(new Error("authorization drain deadline")), timeoutMs);
352	            if (signal?.aborted) abort();
353	          });
354	          const settled = await Promise.race([Promise.allSettled([...mutations]), cancelled]);
355	          signal?.throwIfAborted();
356	          if (performance.now() >= deadline) throw new Error("authorization drain deadline");
357	          check();
358	          const failed = settled.filter((result) => result.status === "rejected");
359	          if (failed.length)
360	            throw new AggregateError(
361	              failed.map((result) => result.reason),
362	              "authorization drain failed",
363	            );
364	          return owner.replaceAuthorizationPolicy();
365	        } finally {
366	          clearTimeout(timer);
367	          if (abort) signal?.removeEventListener("abort", abort);
368	          resume();
369	        }
370	      });
371	    },
372	    closed: completion.promise,
373	    /** Actual fixed-owner Read configuration; no Transactional discovery claims. */
374	    readFor(principal: Parameters<typeof read.readFor>[0]) {
375	      check();
376	      const facet = read.readFor(principal);
377	      const guarded: ReturnType<typeof read.readFor> = {
378	        perform: (request, options) => run(() => facet.perform(request, options)),
379	        resolveAlias: (url, options) => run(() => facet.resolveAlias(url, options)),
380	      };
381	      return Object.freeze(guarded);
382	    },
383	    readAtMinimum(principal: Parameters<typeof read.readFor>[0], minimum: TransactionMinimum) {
384	      check();
385	      const facet = read.minimumFor(principal, snapshotCurrentReadMinimum(minimum));
386	      const guarded: ReturnType<typeof read.readFor> = {
387	        perform: (request, receiving) =>
388	          run(() => {
389	            const capturedRequest = captureTransactionReadRequest(request);
390	            let captured: ReturnType<typeof captureTransactionReadDeliveryOptions>;
391	            try {
392	              captured = captureTransactionReadDeliveryOptions(receiving);
393	            } catch {
394	              // Preserve authority receiving errors without reading a caller
395	              // signal getter or allowing an unconditioned successful fallback.
396	              return facet.perform(capturedRequest, receiving);
397	            }
398	            return waitForTransactionMinimum(
399	              () => facet.perform(capturedRequest, captured),
400	              minimumReads,
401	              captured?.signal,
402	            );
403	          }),
404	        resolveAlias: (url, receiving) =>
405	          run(() => {
406	            let captured: ReturnType<typeof captureTransactionReadDeliveryOptions>;
407	            try {
408	              captured = captureTransactionReadDeliveryOptions(receiving);
409	            } catch {
410	              // Never inspect an unchecked signal while selecting the wait.
411	              return facet.resolveAlias(url, receiving);
412	            }
413	            return waitForTransactionMinimum(
414	              () => facet.resolveAlias(url, captured),
415	              minimumReads,
416	              captured?.signal,
417	            );
418	          }),
419	      };
420	      return Object.freeze(guarded);
421	    },
422	    snapshot(
423	      request: TransactionSnapshotRequest,
424	      supplied?: TransactionMinimum,
425	      signal?: AbortSignal,
426	    ) {
427	      // Without a minimum, preserve the synchronous owner path: it does not
428	      // observe signal or claim interruption of retained reads or copying.
429	      if (supplied === undefined) return run(async () => owner.observeSnapshot(request));
430	      let captured: { minimum: TransactionMinimum } | { error: TypeError };
431	      try {
432	        captured = { minimum: snapshotTransactionMinimum(supplied) };
433	      } catch (error) {
434	        if (!(error instanceof TypeError)) throw error;
435	        captured = { error };
436	      }
437	      let minimum: TransactionMinimum;
438	      let kind: TransactionSnapshotRequest["kind"];
439	      if ("error" in captured) {
440	        // Revalidate only data fields synchronously; kind/lifecycle errors are
441	        // outside both catches. Excluded requests retain the original refusal.
442	        try {
443	          minimum = snapshotCurrentReadMinimum(supplied);
444	        } catch {
445	          throw captured.error;
446	        }
447	        kind = request.kind;
448	        if (kind !== "create" && kind !== "preflight") throw captured.error;
449	      } else {
450	        minimum = captured.minimum;
451	        kind = request.kind;
452	      }
453	      if (kind !== "create" && kind !== "preflight")
454	        throw new TypeError("minimum Snapshot observation requires fresh creation or preflight");
455	      // Freeze both controls before the first asynchronous attempt. Each owner
456	      // entry revalidates the tuple; no SQLite entry survives a finite wait.
457	      const copied = Object.freeze({ kind });
458	      return run(() =>
459	        waitForTransactionMinimum(
460	          () => owner.observeSnapshot(copied, minimum),
461	          minimumReads,
462	          signal,
463	        ),
464	      );
465	    },
466	    changes(
467	      intent: TransactionChangefeedIntent,
468	      supplied?: TransactionMinimum | "unsupported",
469	      signal?: AbortSignal,
470	      admission?: "finite-start-now" | "current-changefeed",
471	    ) {
472	      // Capture controls before asynchronous retries. start=now observes admission
473	      // head once; advancing it at every attempt would skip intervening commits.
474	      const copied =
475	        "after" in intent
