484	          : finiteStartNow || currentChangefeed
485	            ? snapshotCurrentReadMinimum(supplied)
486	            : snapshotTransactionMinimum(supplied);
487	      return run(() => {
488	        const after = "after" in copied ? copied.after : owner.captureChangesStart();
489	        return waitForTransactionMinimum(
490	          () =>
491	            owner.readChanges(
492	              after,
493	              minimum,
494	              currentChangefeed
495	                ? "current-changefeed"
496	                : finiteStartNow
