535	              captured = true;
536	            }
537	            return owner.readEvents(
538	              source,
539	              after,
540	              minimum,
541	              currentEvent ? "current-event" : undefined,
542	            );
543	          },
544	          minimumReads,
545	          signal,
546	        );
547	      });
548	    },
549	    beginEvents(
550	      source: string,
551	      after?: string,
552	      supplied?: TransactionMinimum | "unsupported",
553	      signal?: AbortSignal,
554	      invalidReconnect = false,
555	      admission?: "initial-scope-sse" | "current-event",
