580	        waitForTransactionMinimum(
581	          () =>
582	            owner.beginEventScan(
583	              source,
584	              after,
585	              minimum,
586	              invalidReconnect,
587	              currentEvent
588	                ? "current-event"
589	                : initialScopeSseMinimum
590	                  ? "initial-scope-sse"
591	                  : undefined,
592	            ),
593	          minimumReads,
594	          signal,
595	        ),
596	      );
597	    },
598	    nextEvents(scan: TransactionEventScan, signal?: AbortSignal) {
599	      return run(async () => {
600	        signal?.throwIfAborted();
601	        return owner.advanceEventScan(scan);
602	      });
603	    },
604	    receiptPage(
605	      access:
606	        | { readonly kind: "unauthenticated" }
607	        | { readonly kind: "authenticated"; readonly principal: string },
608	      id: string,
609	      supplied?: TransactionMinimum | "unsupported",
610	    ): Promise<
611	      | {
612	          readonly kind: "page";
613	          readonly page: TransactionReceiptPage;
614	          readonly context: TransactionReadContext;
615	        }
616	      | { readonly kind: "refused"; readonly code: "unauthenticated" }
617	      | {
618	          readonly kind: "refused";
619	          readonly code: "resource-not-found";
620	          readonly context?: TransactionReadContext;
