634	          // Prefix checking is defense in depth, not an independent plan witness.
635	          if (
636	            result.kind === "page" &&
637	            (result.page.results.length < 1 ||
638	              result.page.results.length > maximum ||
639	              (result.page.next !== null &&
640	                (!result.page.next.startsWith(`${result.page.receipt}/pages/`) ||
641	                  result.page.results.length !== maximum)))
642	          )
643	            throw new Error("invalid receipt page projection");
644	          return result.kind === "missing"
645	            ? Object.freeze({
646	                kind: "refused" as const,
647	                code: "resource-not-found" as const,
648	                ...(result.context === undefined ? {} : { context: result.context }),
649	              })
650	            : result;
651	        }, minimumReads);
652	      });
653	    },
654	    receiptAtMinimum(
655	      access:
656	        | { readonly kind: "unauthenticated" }
657	        | { readonly kind: "authenticated"; readonly principal: string },
658	      id: string,
659	      supplied: TransactionMinimum | "unsupported",
660	    ): Promise<TransactionServiceReceiptResult | { readonly kind: "unsupported" }> {
661	      return run(async () => {
662	        if (access.kind === "unauthenticated")
663	          return Object.freeze({ kind: "refused", status: 401, code: "unauthenticated" });
664	        const principal = access.principal;
665	        if (supplied === "unsupported") {
666	          const observed = owner.readReceipt(principal, id, supplied);
667	          if ("kind" in observed) return observed;
668	          return Object.freeze({
669	            kind: "refused",
670	            status: 404,
671	            code: "resource-not-found",
672	            context: observed.context,
673	          });
674	        }
675	        const minimum = snapshotCurrentReadMinimum(supplied);
676	        return waitForTransactionMinimum(() => receipt(principal, id, minimum), minimumReads);
677	      });
678	    },
679	    submit(request: TransactionSubmission): Promise<TransactionServiceSubmissionResult> {
680	      return mutate(async () => {
681	        const authorization = Object.freeze({ ...request.authorization });
682	        const result = await submitTransaction(
683	          owner,
684	          { ...request, authorization },
685	          comparison,
686	          true,
687	        );
688	        if (result.kind !== "receipt") return result;
689	        if (authorization.kind !== "authorized") throw new Error("unauthorized receipt delivery");
690	        if (!result.context)
691	          throw new Error("admitted receipt lost same-entry observation", {
692	            cause: { id: result.receipt.id, key: result.receipt.idempotencyKey },
693	          });
694	        return checked({ receipt: result.receipt, context: result.context });
695	      });
696	    },
697	    /** Trusted prepared carrier + authenticated principal. Raw sequence receiving
698	     * order/media/negotiation is intentionally left to the later HTTP boundary. */
699	    sequence(
700	      principal: string,
701	      sequence: PreparedTransactionSequence,
702	    ): Promise<TransactionSequenceResponse> {
703	      return mutate(() => executeSequence(principal, sequence));
704	    },
705	    /** Authenticated exact local schema response. Capture before asynchronous work;
706	     * a minimum wait never retains an owner entry. No-minimum timing is unchanged. */
707	    schemaObserved(supplied?: TransactionMinimum, signal?: AbortSignal) {
708	      const minimum = supplied === undefined ? undefined : snapshotCurrentReadMinimum(supplied);
709	      const observe = () => {
710	        const observed = owner.withRead((_reader, context) => {
711	          if (minimum !== undefined) checkCurrentReadMinimum(minimum, context, true);
712	          return Object.freeze({ context });
713	        });
714	        if (observed.kind === "entry-refused")
715	          throw new Error("transaction schema observation refused", { cause: observed.cause });
716	        return observed.value;
717	      };
718	      if (minimum === undefined) return run(async () => observe());
719	      return run(async () => waitForTransactionMinimum(observe, minimumReads, signal));
720	    },
721	    /** Trusted HTTP refusal after carrier/auth checks. Observe without executing
722	     * members or admitting keys; an unavailable owner remains an internal fault. */
723	    sequenceRefusalObserved() {
724	      return run(async () => {
725	        const observed = owner.withRead((_reader, context) => Object.freeze({ context }));
726	        if (observed.kind === "entry-refused")
727	          throw new Error("transaction sequence refusal observation refused", {
728	            cause: observed.cause,
729	          });
730	        return observed.value;
731	      });
732	    },
733	    /** Project stable member execution facts in the current serving entry after
734	     * ordered execution. Version erasure remains outside this private policy. */
735	    sequenceObserved(principal: string, sequence: PreparedTransactionSequence) {
736	      return mutate(async () => {
737	        const response = await executeSequence(principal, sequence);
738	        const observed = owner.withRead((reader, context) => {
739	          const policy = owner.captureReadAuthorization(reader, {
740	            kind: "authenticated",
741	            principal: { id: principal },
742	          });
743	          const body = {
744	            results: response.results.map((entry) =>
745	              projectTransactionEntry(entry, policy.readPolicy === "all-visible"),
746	            ),
747	          };
748	          // Traverse frozen parents too: this observation guarantees every descendant is frozen.
749	          const freeze = (value: unknown): void => {
750	            const pending: unknown[] = [value];
751	            while (pending.length) {
752	              const node = pending.pop();
753	              if (node !== null && typeof node === "object") {
754	                for (const child of Object.values(node)) pending.push(child);
755	                Object.freeze(node);
756	              }
757	            }
758	          };
759	          freeze(body);
760	          return Object.freeze({ body, context });
761	        });
762	        if (observed.kind === "entry-refused")
763	          throw new Error("transaction sequence observation refused", { cause: observed.cause });
764	        return observed.value;
765	      });
766	    },
767	    /** Authentication is transport-supplied, never inferred from actor or URL.
768	     * Current owner policy projects contents; principal binding denies foreign
769	     * receipts uniformly. No key lookup, receipt listing or fabricated page URL. */
770	    receipt(
771	      access:
772	        | { readonly kind: "unauthenticated" }
773	        | { readonly kind: "authenticated"; readonly principal: string },
774	      id: string,
775	    ): TransactionServiceReceiptResult {
776	      check();
777	      if (access.kind === "unauthenticated")
778	        return Object.freeze({ kind: "refused", status: 401, code: "unauthenticated" });
779	      return receipt(access.principal, id);
780	    },
781	    /** Stop accepting work, drain admitted work even when the client dropped its
782	     * delivery, then close cursors and this service-owned database. No disconnect
783	     * cancellation of accepted writes exists: stream cancellation is separate. */
784	    close(): Promise<void> {
785	      if (closing) return closing;
786	      accepting = false;
787	      closing = (async () => {
788	        for (const controller of streams.keys()) controller.abort(new Error("service shutdown"));
789	        await Promise.allSettled([...streams.values(), ...active]);
790	        const errors: unknown[] = [];
791	        try {
792	          await read.close();
793	        } catch (error) {
794	          errors.push(error);
795	        }
796	        try {
797	          owner.close();
798	        } catch (error) {
799	          errors.push(error);
800	        }
801	        if (errors.length) throw new AggregateError(errors, "transaction service shutdown failed");
802	      })();
803	      void closing.then(completion.resolve, completion.reject);
804	      return closing;
805	    },
806	  });
807	}
