+  let removed = false;
+  try {
+    await g09ServiceBound(run(f), 3000);
+  } catch (error) {
+    failures.push(error);
+  } finally {
+    try {
+      await g09ServiceBound(f.service.close(), 1000);
+      if (!f.closed()) throw new Error("G09 owner close unobserved");
+      rmSync(path.dirname(f.file), { recursive: true });
+      removed = true;
