404	/**
405	 * Converts a Node HTTP request target into the canonical public Scope origin.
406	 * The listener's bind authority and untrusted forwarding headers never define
407	 * protocol identity; only the incoming path/query are retained.
408	 */
409	function createCanonicalHttpRequest(
410	  scope: AbsoluteHttpUrl,
411	  requestTarget: string | undefined,
412	  options: NodeHttpRequestOptions = {},
413	): Request {
414	  const target = requestTarget ?? "/";
415	  const canonicalOrigin = `${new URL(scope).origin}/`;
416	  const pathAndQuery = normalizationSafeRawRequestPath(target);
417	  const canonical = new URL(pathAndQuery ?? ".bdp-invalid-request-target", canonicalOrigin);
418	  return new Request(canonical, {
419	    ...(options.method === undefined ? {} : { method: options.method }),
420	    ...(options.signal === undefined ? {} : { signal: options.signal }),
421	    ...(options.headers === undefined ? {} : { headers: options.headers }),
422	  });
423	}
424	
425	function nodeRequestHeaders(rawHeaders: readonly string[]): Headers {
426	  const headers = new Headers();
427	  for (let index = 0; index + 1 < rawHeaders.length; index += 2) {
428	    const name = rawHeaders[index];
429	    const value = rawHeaders[index + 1];
430	    if (name !== undefined && value !== undefined) headers.append(name, value);
431	  }
432	  return headers;
433	}
