435	/**
436	 * Owns the complete Node-to-Web HTTP bridge used by both executable targets.
437	 * Unsupported methods are rejected before Fetch's Request constructor can
438	 * reject forbidden tokens such as TRACE or CONNECT.
439	 */
440	function createNodeRequestListener(
441	  scope: AbsoluteHttpUrl,
442	  handler: HttpHandler,
443	  options: NodeRequestListenerOptions = {},
444	): RequestListener {
445	  return async (incoming, outgoing) => {
446	    try {
447	      const method = incoming.method ?? "GET";
448	      if (method !== "GET" && method !== "HEAD") {
449	        incoming.resume();
450	        outgoing.statusCode = 405;
451	        outgoing.setHeader("allow", "GET, HEAD");
452	        outgoing.setHeader("content-length", 0);
453	        outgoing.end();
454	        return;
455	      }
456	      const signal = createNodeHttpDisconnectSignal(incoming, outgoing);
457	      const request = createCanonicalHttpRequest(scope, incoming.url, {
458	        method,
459	        signal,
460	        headers: nodeRequestHeaders(incoming.rawHeaders),
461	      });
462	      const response = await handler(request);
463	      if (outgoing.destroyed) return;
464	      outgoing.statusCode = response.status;
465	      response.headers.forEach((value, key) => {
466	        outgoing.setHeader(key, value);
467	      });
468	      const body = response.body === undefined ? undefined : stringifyJsonValue(response.body);
469	      if (body !== undefined && !response.headers.has("content-length")) {
470	        outgoing.setHeader("content-length", Buffer.byteLength(body));
471	      }
472	      outgoing.end(method === "HEAD" ? undefined : body);
473	    } catch (error) {
474	      if (error instanceof ScopeServerOperationAbortedError) {
475	        outgoing.destroy();
476	        return;
477	      }
478	      options.onError?.(error);
479	      if (outgoing.destroyed) return;
480	      if (outgoing.headersSent) {
481	        outgoing.destroy();
482	        return;
483	      }
484	      for (const name of outgoing.getHeaderNames()) outgoing.removeHeader(name);
485	      outgoing.statusCode = 500;
486	      outgoing.setHeader("content-length", 0);
487	      outgoing.end();
488	    }
489	  };
490	}
