493	export function createNodeHttpServer(
494	  server: ReadServer,
495	  options: NodeRequestListenerOptions = {},
496	): NodeHttpServer {
497	  if (!verifiedReadServers.has(server)) {
498	    throw new TypeError("createNodeHttpServer requires a server created by createReadServer");
499	  }
500	  const maxHeaderSize = nodeHeaderSizeForReadServer.get(server);
501	  if (maxHeaderSize !== undefined && maxHeaderSize > MAX_NODE_HEADER_SIZE) {
502	    throw new RangeError("Server Selector byte limit exceeds the safe Node transport ceiling");
503	  }
504	  const listener = createNodeServer(
505	    { maxHeaderSize },
506	    createNodeRequestListener(server.scope, createHttpHandler(server), options),
507	  );
508	  listener.on("connect", (_request, socket) => {
509	    socket.on("error", () => undefined);
510	    socket.end(
511	      "HTTP/1.1 405 Method Not Allowed\r\nAllow: GET, HEAD\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
512	      () => socket.destroy(),
513	    );
514	  });
515	  verifiedNodeHttpServers.add(listener);
516	  return listener;
517	}
