553	/** Closes a verified listener, forcibly draining slow peers after a bounded grace period. */
554	export function closeNodeHttpServer(
555	  listener: NodeHttpServer,
556	  options: NodeHttpCloseOptions = {},
557	): Promise<void> {
558	  if (!verifiedNodeHttpServers.has(listener)) {
559	    throw new TypeError("closeNodeHttpServer requires a listener created by createNodeHttpServer");
560	  }
561	  if (!listener.listening) return Promise.resolve();
562	  const forceAfterMilliseconds = options.forceAfterMilliseconds ?? 1_000;
563	  return new Promise((resolve, reject) => {
564	    let forceTimer: ReturnType<typeof setTimeout> | undefined;
565	    listener.close((error) => {
566	      if (forceTimer !== undefined) clearTimeout(forceTimer);
567	      if (error) reject(error);
568	      else resolve();
569	    });
570	    listener.closeIdleConnections();
571	    forceTimer = setTimeout(() => listener.closeAllConnections(), forceAfterMilliseconds);
572	    forceTimer.unref();
573	  });
574	}
