576	/** Owns one Node listener and its ReadServer through bind, termination, and cleanup. */
577	export async function serveNodeHttpServer(
578	  server: ReadServer,
579	  options: NodeHttpServeOptions,
580	): Promise<NodeHttpServeResult> {
581	  const listener = createNodeHttpServer(
582	    server,
583	    options.onRequestError === undefined ? {} : { onError: options.onRequestError },
584	  );
585	  const processTermination =
586	    options.terminationSignal === undefined ? createProcessTerminationSignal() : undefined;
587	  const terminationSignal = options.terminationSignal ?? processTermination?.signal;
588	  if (terminationSignal === undefined) throw new TypeError("termination signal was not created");
589	  const termination = observeTermination(terminationSignal);
590	  let reportListenerFailure: (error: NodeHttpListenerError) => void = () => undefined;
591	  const listenerFailure = new Promise<NodeHttpListenerError>((resolve) => {
592	    reportListenerFailure = resolve;
593	  });
594	  let outcome: NodeHttpServeResult | undefined;
595	  let primaryFailed = false;
596	  let primaryError: unknown;
597	  try {
598	    await listenNodeHttpServer(listener, {
599	      host: options.host,
600	      port: options.port,
601	      onError: reportListenerFailure,
602	    });
603	    options.onStarted?.();
604	    outcome = await Promise.race([
605	      termination.promise.then((signal) => ({
606	        kind: "signal" as const,
607	        signal,
608	      })),
609	      listenerFailure.then((error) => ({ kind: "listener-failure" as const, error })),
610	    ]);
611	  } catch (error) {
612	    primaryFailed = true;
613	    primaryError = error;
614	  } finally {
615	    termination.dispose();
616	    processTermination?.dispose();
617	  }
618	  const cleanup = await Promise.allSettled([closeNodeHttpServer(listener), server.close()]);
619	  const cleanupFailures = cleanup
620	    .filter((result): result is PromiseRejectedResult => result.status === "rejected")
621	    .map(({ reason }) => reason);
622	  if (primaryFailed) {
623	    if (cleanupFailures.length > 0)
624	      throw new AggregateError(
625	        [primaryError, ...cleanupFailures],
626	        "Node Read server operation and cleanup failed",
627	      );
628	    throw primaryError;
629	  }
630	  if (cleanupFailures.length > 0)
631	    throw new AggregateError(cleanupFailures, "Node Read server cleanup failed");
632	  if (outcome === undefined) throw new TypeError("Node Read server produced no stop outcome");
633	  return outcome;
634	}
